[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a3a5c;
    --accent: #2980b9;
    --accent2: #e67e22;
    --fiction: #2980b9;
    --nonfiction: #e67e22;
    --bg: #f8f9fb;
    --card: #ffffff;
    --text: #1a1a2e;
    --muted: #6b7280;
    --border: #e2e8f0;
    --green: #27ae60;
    --red: #e74c3c;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }
  /* Header */
  .report-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 60%, #3a7ebf 100%);
    color: white;
    padding: 48px 60px 40px;
  }
  .report-header .badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.3);
    border-radius: 20px;
    padding: 4px 14px;
    font-size: 12px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 16px;
  }
  .report-header h1 {
    font-size: 2.2rem;
    font-weight: 700;
    line-height: 1.25;
    margin-bottom: 12px;
    max-width: 750px;
  }
  .report-header p {
    font-size: 1.05rem;
    opacity: 0.85;
    max-width: 650px;
    margin-bottom: 28px;
  }
  .header-meta {
    display: flex;
    gap: 32px;
    font-size: 13px;
    opacity: 0.7;
    flex-wrap: wrap;
  }
  .header-meta span { display: flex; align-items: center; gap: 6px; }

  /* Layout */
  .report-body { max-width: 1100px; margin: 0 auto; padding: 40px 32px 60px; }

  /* Section */
  .section { margin-bottom: 56px; }
  .section-header {
    display: flex;
    align-items: baseline;
    gap: 14px;
    margin-bottom: 28px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--border);
  }
  .section-number {
    font-size: 13px;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    white-space: nowrap;
  }
  .section-header h2 {
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--primary);
  }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 8px;
  }
  .kpi-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 22px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }
  .kpi-card.blue::before { background: var(--accent); }
  .kpi-card.orange::before { background: var(--accent2); }
  .kpi-card.green::before { background: var(--green); }
  .kpi-card.red::before { background: var(--red); }
  .kpi-card.purple::before { background: #8e44ad; }
  .kpi-label { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 8px; }
  .kpi-value { font-size: 2rem; font-weight: 800; color: var(--primary); line-height: 1; margin-bottom: 6px; }
  .kpi-sub { font-size: 12px; color: var(--muted); }

  /* Chart containers */
  .chart-row { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 24px; }
  .chart-row.full { grid-template-columns: 1fr; }
  .chart-row.thirds { grid-template-columns: 1fr 1fr 1fr; }
  .chart-box {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
  }
  .chart-box h3 {
    font-size: 14px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 4px;
  }
  .chart-subtitle {
    font-size: 12px;
    color: var(--muted);
    margin-bottom: 16px;
  }
  .chart-wrap { position: relative; height: 260px; }
  .chart-wrap.tall { height: 320px; }
  .chart-wrap.short { height: 200px; }

  /* Insight box */
  .insight {
    background: #eef6ff;
    border-left: 4px solid var(--accent);
    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
    margin-top: 16px;
    font-size: 14px;
    color: var(--primary);
  }
  .insight strong { color: var(--accent); }

  /* Genre comparison table */
  .compare-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
    background: var(--card);
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid var(--border);
  }
  .compare-table th {
    background: var(--primary);
    color: white;
    padding: 12px 18px;
    text-align: left;
    font-size: 13px;
    font-weight: 600;
  }
  .compare-table th.fiction { background: var(--fiction); }
  .compare-table th.nonfiction { background: var(--nonfiction); }
  .compare-table td {
    padding: 11px 18px;
    border-bottom: 1px solid var(--border);
    vertical-align: middle;
  }
  .compare-table tr:last-child td { border-bottom: none; }
  .compare-table tr:nth-child(even) td { background: #f8fafc; }
  .compare-table .metric-name { font-weight: 600; color: var(--primary); }
  .compare-table .val { font-weight: 700; font-size: 15px; }
  .compare-table .val.blue { color: var(--fiction); }
  .compare-table .val.orange { color: var(--nonfiction); }
  .badge-winner {
    display: inline-block;
    background: #e8f5e9;
    color: #2e7d32;
    border-radius: 12px;
    padding: 2px 9px;
    font-size: 11px;
    font-weight: 700;
    margin-left: 8px;
  }

  /* Authors table */
  .authors-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    overflow: hidden;
  }
  .authors-table th {
    background: #f1f5f9;
    padding: 11px 16px;
    text-align: left;
    font-size: 12px;
    font-weight: 700;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 2px solid var(--border);
  }
  .authors-table td { padding: 10px 16px; border-bottom: 1px solid var(--border); }
  .authors-table tr:last-child td { border-bottom: none; }
  .authors-table tr:hover td { background: #f8faff; }
  .rank { font-weight: 800; color: var(--muted); font-size: 13px; }
  .rank.gold { color: #d4a017; }
  .rank.silver { color: #9e9e9e; }
  .rank.bronze { color: #c47722; }
  .bar-inline {
    display: inline-block;
    height: 8px;
    border-radius: 4px;
    background: var(--accent);
    vertical-align: middle;
    margin-left: 8px;
  }

  /* Price segment visual */
  .price-seg-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
  }
  .price-seg-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 16px 14px;
    text-align: center;
  }
  .price-seg-label { font-size: 13px; font-weight: 700; color: var(--primary); margin-bottom: 8px; }
  .price-seg-rating { font-size: 1.8rem; font-weight: 800; color: var(--accent); margin-bottom: 4px; }
  .price-seg-n { font-size: 11px; color: var(--muted); }
  .price-seg-bar { height: 4px; border-radius: 2px; background: #e2e8f0; margin-top: 10px; overflow: hidden; }
  .price-seg-bar-fill { height: 100%; border-radius: 2px; background: var(--accent); }

  /* Recommendations */
  .rec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
  .rec-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px;
    position: relative;
  }
  .rec-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    border-radius: 10px 10px 0 0;
  }
  .rec-card.r1::before { background: var(--accent); }
  .rec-card.r2::before { background: var(--accent2); }
  .rec-card.r3::before { background: var(--green); }
  .rec-card.r4::before { background: #8e44ad; }
  .rec-num { font-size: 11px; font-weight: 700; color: var(--muted); letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 8px; }
  .rec-card h3 { font-size: 15px; font-weight: 700; color: var(--primary); margin-bottom: 10px; }
  .rec-card p { font-size: 13.5px; color: #374151; line-height: 1.6; margin-bottom: 10px; }
  .rec-source { font-size: 12px; color: var(--accent); font-style: italic; }

  /* Footer */
  .report-footer {
    background: var(--primary);
    color: rgba(255,255,255,0.6);
    padding: 24px 60px;
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
  }
  .report-footer span { color: rgba(255,255,255,0.4); }

  /* Annotation pill */
  .pill {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 700;
    vertical-align: middle;
  }
  .pill.blue { background: #dbeafe; color: #1d4ed8; }
  .pill.orange { background: #fef3c7; color: #b45309; }

  /* inflection marker */
  .inflection-note {
    background: #fffbeb;
    border: 1px solid #fcd34d;
    border-radius: 8px;
    padding: 10px 16px;
    font-size: 13px;
    color: #78350f;
    margin-top: 10px;
  }

  @media (max-width: 700px) {
    .report-header { padding: 32px 20px 28px; }
    .report-body { padding: 28px 16px 48px; }
    .chart-row { grid-template-columns: 1fr; }
    .chart-row.thirds { grid-template-columns: 1fr; }
    .kpi-grid { grid-template-columns: 1fr 1fr; }
    .rec-grid { grid-template-columns: 1fr; }
    .price-seg-grid { grid-template-columns: 1fr 1fr; }
  }
</style>
</head>
<body>

<!-- ═══════════════════════════════════ HEADER ═══════════════════════════════════ -->
<div class="report-header">
  <div class="badge">Management Report · Trend Analysis</div>
  <h1>Amazon Bestselling Books<br>Price vs. User Rating Analysis</h1>
  <p>Does price drive customer satisfaction — or is it disconnected from the ratings that keep books on the bestseller list? A decade of Amazon data (2009–2019) delivers a clear answer.</p>
  <div class="header-meta">
    <span>📅 Coverage: 2009–2019</span>
    <span>📚 550 annual bestseller records</span>
    <span>📊 50 top titles per year</span>
    <span>🏷️ Fiction &amp; Non-Fiction</span>
  </div>
</div>

<div class="report-body">

<!-- ═══════════════════════════════ SECTION 1: MARKET OVERVIEW ═══════════════════════════════ -->
<div class="section">
  <div class="section-header">
    <span class="section-number">01</span>
    <h2>Bestseller Market Overview (2009–2019)</h2>
  </div>

  <div class="kpi-grid">
    <div class="kpi-card blue">
      <div class="kpi-label">Total Records</div>
      <div class="kpi-value">550</div>
      <div class="kpi-sub">50 bestsellers × 11 years</div>
    </div>
    <div class="kpi-card orange">
      <div class="kpi-label">Avg. User Rating</div>
      <div class="kpi-value">4.62</div>
      <div class="kpi-sub">Out of 5.0 scale</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-label">Avg. List Price</div>
      <div class="kpi-value">$13.10</div>
      <div class="kpi-sub">Integer USD; range $0–$105</div>
    </div>
    <div class="kpi-card red">
      <div class="kpi-label">Avg. Review Count</div>
      <div class="kpi-value">11,953</div>
      <div class="kpi-sub">Per book-year entry</div>
    </div>
    <div class="kpi-card purple">
      <div class="kpi-label">Non-Fiction Share</div>
      <div class="kpi-value">56.4%</div>
      <div class="kpi-sub">310 of 550 records</div>
    </div>
  </div>

  <div class="chart-row" style="margin-top:24px;">
    <div class="chart-box">
      <h3>Genre Distribution Across the Decade</h3>
      <div class="chart-subtitle">Annual count of Fiction vs. Non-Fiction bestsellers</div>
      <div class="chart-wrap">
        <canvas id="genreBarChart"></canvas>
      </div>
    </div>
    <div class="chart-box">
      <h3>Review Volume Growth</h3>
      <div class="chart-subtitle">Average review count per year — a proxy for engagement</div>
      <div class="chart-wrap">
        <canvas id="reviewsChart"></canvas>
      </div>
    </div>
  </div>
  <div class="insight">
    <strong>Key context:</strong> Non-Fiction consistently outpaces Fiction on the bestseller list (56% vs. 44% of all records). Average review counts nearly tripled from 4,710 (2009) to 15,898 (2019), indicating a deepening pool of socially-validated titles — and raising the bar for new entrants.
  </div>
</div>

<!-- ═══════════════════════════════ SECTION 2: CORRELATION ═══════════════════════════════ -->
<div class="section">
  <div class="section-header">
    <span class="section-number">02</span>
    <h2>Price vs. User Rating: Correlation Analysis</h2>
  </div>

  <div class="kpi-grid" style="margin-bottom:24px;">
    <div class="kpi-card blue">
      <div class="kpi-label">Pearson r (Price × Rating)</div>
      <div class="kpi-value">−0.133</div>
      <div class="kpi-sub">Weak negative correlation across all 550 records</div>
    </div>
    <div class="kpi-card orange">
      <div class="kpi-label">Best-Rated Price Band</div>
      <div class="kpi-value">Free ($0)</div>
      <div class="kpi-sub">Avg. 4.77 rating (n=12)</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-label">Worst-Rated Price Band</div>
      <div class="kpi-value">$10–$19</div>
      <div class="kpi-sub">Avg. 4.56 rating (n=227)</div>
    </div>
  </div>

  <div class="chart-row full">
    <div class="chart-box">
      <h3>Price vs. User Rating — Scatter Plot</h3>
      <div class="chart-subtitle">Each point = one bestseller record. <span class="pill blue">Blue = Fiction</span> <span class="pill orange">Orange = Non-Fiction</span></div>
      <div class="chart-wrap tall">
        <canvas id="scatterChart"></canvas>
      </div>
    </div>
  </div>

  <div style="margin-top: 20px;">
    <div class="chart-box">
      <h3>Average Rating by Price Segment</h3>
      <div class="chart-subtitle">Higher price does not consistently yield higher ratings</div>
      <div class="price-seg-grid" style="margin-top: 16px;">
        <div class="price-seg-card">
          <div class="price-seg-label">Free ($0)</div>
          <div class="price-seg-rating">4.77</div>
          <div class="price-seg-n">n = 12</div>
          <div class="price-seg-bar"><div class="price-seg-bar-fill" style="width:87%"></div></div>
        </div>
        <div class="price-seg-card">
          <div class="price-seg-label">$1 – $9</div>
          <div class="price-seg-rating">4.67</div>
          <div class="price-seg-n">n = 226</div>
          <div class="price-seg-bar"><div class="price-seg-bar-fill" style="width:77%"></div></div>
        </div>
        <div class="price-seg-card">
          <div class="price-seg-label">$10 – $19</div>
          <div class="price-seg-rating">4.56</div>
          <div class="price-seg-n">n = 227</div>
          <div class="price-seg-bar"><div class="price-seg-bar-fill" style="width:62%"></div></div>
        </div>
        <div class="price-seg-card">
          <div class="price-seg-label">$20 – $29</div>
          <div class="price-seg-rating">4.61</div>
          <div class="price-seg-n">n = 54</div>
          <div class="price-seg-bar"><div class="price-seg-bar-fill" style="width:70%"></div></div>
